class Solution {
public:
    vector<int> rearrangeBarcodes(vector<int>& barcodes) {
        int n = barcodes.size();
        if (n <= 1) return barcodes;
        int cnt[10001] = {0};
        int maxCnt = 0, maxVal = 0;
        for (int b : barcodes) {
            cnt[b]++;
            if (cnt[b] > maxCnt) {
                maxCnt = cnt[b];
                maxVal = b;
            }
        }
        vector<int> res(n);
        int idx = 0;
        for (int i = 0; i < maxCnt; i++) {
            res[idx] = maxVal;
            idx += 2;
            if (idx >= n) idx = 1;
        }
        for (int v = 1; v <= 10000; v++) {
            if (v == maxVal) continue;
            while (cnt[v] > 0) {
                res[idx] = v;
                idx += 2;
                if (idx >= n) idx = 1;
                cnt[v]--;
            }
        }
        return res;
    }
};
